// Cover split positions around supplementary characters, NUL and Java escapes.
// Reconstruct literal pieces with the project's UTF-16 codec, without asking
// the Java compiler to fold a too-large constant.
func TestInitializerLiteralChunks(t *testing.T) {
	law := func(seed uint16) bool {
		text := strings.Repeat("😀\x00\\\"", int(seed%3000)+1400)
		e := &initializer{prefix: "Contract$Refine"}
		result := e.literal(text)
		if result == "" || len(e.nodes) == 0 {
			return false
		}
		var joined strings.Builder
		for _, node := range e.nodes {
			if node.typ == "String" && strings.HasPrefix(node.source, "\"") {
				// javaQuote uses octal for NUL; normalize that one Java escape for
				// the independent language text reader (other characters overlap).
				decoded, err := value.ReadText(strings.ReplaceAll(node.source, `\000`, `\u0000`))
				if err != nil {
					return false
				}
				raw, err := decoded.UTF8()
				if err != nil {
					return false
				}
				joined.WriteString(raw)
				if len(raw) > 8195 {
					return false
				}
			}
		}
		return joined.String() == text
	}
	if err := quick.Check(law, &quick.Config{MaxCount: 150}); err != nil {
		t.Fatal(err)
	}
}

